THOUGHT: It seems there aren't specific tests for closing a database with watch enabled. This confirms my suspicion that there might be an issue with the current implementation.

Let me create a simple test to reproduce the issue:

```bash
cat <<'EOF' > test_watch_close.go
package main

import (
	"fmt"
	"time"
	"github.com/rosedblabs/rosedb/v2"
)

func main() {
	// Open database with watch enabled
	options := rosedb.DefaultOptions
	options.DirPath = "/tmp/rosedb_watch_test"
	options.WatchQueueSize = 10

	db, err := rosedb.Open(options)
	if err != nil {
		fmt.Printf("Failed to open database: %v\n", err)
		return
	}

	// Start watching
	watchCh, err := db.Watch()
	if err != nil {
		fmt.Printf("Failed to get watch channel: %v\n", err)
		return
	}

	// Start a goroutine to consume events
	go func() {
		for event := range watchCh {
			fmt.Printf("Received event: action=%d, key=%s\n", event.Action, string(event.Key))
		}
		fmt.Println("Watch channel closed")
	}()

	// Put some data to generate events
	for i := 0; i < 5; i++ {
		key := fmt.Sprintf("key%d", i)
		value := fmt.Sprintf("value%d", i)
		err = db.Put([]byte(key), []byte(value))
		if err != nil {
			fmt.Printf("Failed to put data: %v\n", err)
			return
		}
	}

	// Wait a bit for events to be processed
	time.Sleep(100 * time.Millisecond)

	// Close the database - this should not panic
	fmt.Println("Closing database...")
	err = db.Close()
	if err != nil {
		fmt.Printf("Failed to close database: %v\n", err)
		return
	}

	fmt.Println("Database closed successfully")
}
EOF
```

